INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('las-vegas-blackjack', 41544, '1978-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dvk9pngxf0zrxcwhu3wz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6kvv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Las Vegas Blackjack!', 'The computer is the dealer. The object of the game is to get a higher count of cards than the dealer, up to but not over 21. If a player draws cards with a point value over 21, the hand is a BUST, and he loses his bet to the dealer. If the dealer''s goes BUST, he pays off each of the remaining players. A player may "draw" any number of cards until he reaches or exceeds a total of 21. The dealer must "draw" a card on 16 or less and "stick" with his hand on 17 or more. An ace counts as either 1 or 11 at the player''s discretion. Kings, queens and jacks count as 10 each. All other cards count as their face value.' FROM games WHERE igdb_id = 41544 ON CONFLICT (game_id, language_code) DO NOTHING;
