INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('videocart-19-checkers', 41225, '1978-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co70b7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/glywr39indkrajlctg88.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videocart-19: Checkers', 'A playable version of the board game of Checkers. The player controls the 12 checkers at the bottom of the screen and attempts to remove the 12 checkers at the top of the screen, controlled by the computer. A player can only move his checkers diagonally toward his opponent''s side of the board. A checker can be jumped when two opposing checkers are adjacent to each other and there is an empty space directly across the checker being jumped. If there''s a checker in the board that a player can jump, he is forced to do so. If a checker reaches the other side of the board, that checker is kinged and is allowed to move and jump both back and forth in diagonal movements. The game is won by the player who removes all of his opponent''s checkers from the board. This preprogrammed cartridge plugs into the console of the Fairchild Video Entertainment System for more TV fun on the Channel F Network. The classic game of checkers is played against the computer. Here is your chance to sharpen your skills without your opponent dumping the checkerboard on your head. Check it out.' FROM games WHERE igdb_id = 41225 ON CONFLICT (game_id, language_code) DO NOTHING;
