INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('videocart-21-bowling', 41231, '1978-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co70bj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/c04dxd1j0luq0vbqpwzg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videocart-21: Bowling', 'The object of the game is to knock down as many pins in 10 frames of bowling. The game gives the player an overhead view of a bowling lane. The player''s bowling ball starts out moving left and right across the front of the lane. This has the player trying to get the lane position they want the ball to start traveling down. Once the ball starts rolling down the lane, the player can curve the ball left or right. Once the curve has started, it can''t be changed further. The game has 18 variations. They involve choosing the combination of number of players (1 or 2), then speed of play (slow, normal, fast, and fastest), and selecting a regular or split game. Regular games start with all pins standing in each frame while the split games have a random number of pins missing and the player has 2 balls to knock down the remaining ones. This preprogrammed cartridge plugs into the console of the Fairchild Video Entertainment System for more TV fun on the Channel F Network.' FROM games WHERE igdb_id = 41231 ON CONFLICT (game_id, language_code) DO NOTHING;
