INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Incredible Hulk Escapes', 'The Incredible Hulk Escapes is a simple handheld game mostly based on random luck. The player presses a button to which different lights will light up leading to different scores. The scores need to be counted up manually and added to the score wheel while the Hulk climbs higher and higher. The game can be played with two players.' FROM games WHERE igdb_id = 245595 ON CONFLICT (game_id, language_code) DO NOTHING;
