INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Amazing Spider-Man Rescue', '"The Amazing Spider-Man Rescue" is a simple portable game that is mostly based on random luck. The player presses a button, after which various lights illuminate, accumulating different points. These points need to be manually counted and added to the score wheel as Spider-Man climbs higher and higher. The game can be played with two players. The game is functionally identical to The Incredible Hulk Escapes.' FROM games WHERE igdb_id = 245588 ON CONFLICT (game_id, language_code) DO NOTHING;
