INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flag Capture', 'Flag Capture was one of the eleven Atari 2600 titles that were part of the second wave of games released in 1978. It can best be compared to a very early and primitive Minesweeper. One or two players must attempt to discover which tile a flag is hidden under. Players are given clues such as directional arrows which indicate the flags location, or numeric tiles which indicate the flag''s distance. Players must also watch out for bombs which explode if revealed.' FROM games WHERE igdb_id = 17024 ON CONFLICT (game_id, language_code) DO NOTHING;
