INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('speedway-slash-spin-out-slash-crypto-logic', 93319, '1978-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1sqt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc78hi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speedway! / Spin-Out! / Crypto-Logic!', 'Three games are available in this compilation:  - Speedway! (selected by pressing "1") is a vertical scrolling racing game against the clock. The player controls the car with the joystick, pushing up to accelerate it (the longer, the faster), left and right to control direction and down to break.  - Spin-Out! (selected by pressing "2" for a three laps event or "3" for a 15 laps event) is a top-down circuit racing game. Two players race against each other for the amount of tracks selected. Four skill levels are available: clear track/slow speed, clear track/fast speed, barrier track/slow speed and barrier track/fast speed.  - Crypto-Logic! (selected by pressing "4") is a puzzle game. The object is to decipher a scrambled word entered by another player.' FROM games WHERE igdb_id = 93319 ON CONFLICT (game_id, language_code) DO NOTHING;
