INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tank/Plane Battle', '26 games in all, there are 16 tank games for shooting at each other on dangerous terrain and 10 more aircraft and jetfighter battles in stormy skies. And if you shoot it out at night, you can only fire at your enemy by revealing your own position. Resembles Atari 2600 Combat (even with a "Tank Pong" variant), and like the first Combat prototype, it disables the score display whilst sprites are on the screen.' FROM games WHERE igdb_id = 18606 ON CONFLICT (game_id, language_code) DO NOTHING;
