INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-game-of-concentration', 40723, '1978-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/gjdnmnguio2umao9fmxo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc78ld.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Game of Concentration', 'The game is played using a matrix of numbered panels, either 4 x 4 (for 16 panels) or 5 x 6 (for 30 panels). Using the keypad, players enter the number of the panels they wish to reveal. If the images behind the two panels match, the panels are removed and the player scores 1 or 2 points, depending on what difficulty the switch is set to, along with an extra turn. The game has a total of eight variations, four each for each matrix size and four have wild cards. Each matrix can be played by either a single player or by two players taking turns; in single-player games, the player attempts to clear the matrix with as few incorrect matches as possible. Also, players can enable wild cards that will match any image on the board.' FROM games WHERE igdb_id = 40723 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 40723 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
