INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atari Football', 'Atari Football is a 2-player 1978 arcade game in which the sport of American football is accurately emulated, with players represented by Xs and Os. The game was one of the most popular arcade games in its day and is credited with popularizing the trackball. Twenty-five cents would allow 90 seconds of playtime, while adding more quarters would allow longer play. Considered physically exhausting to play, Atari Football involves spinning the trackball as fast as possible to win the game. Just 90 seconds of play could result in sore palms, and longer could cause blisters.' FROM games WHERE igdb_id = 16760 ON CONFLICT (game_id, language_code) DO NOTHING;
