INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slot Racers', 'Slot Racers is a joystick-controlled action game, with a total of nine game variations programmed within the cartridge. The object of the game is to pilot your car through a maze, while attempting to fire missiles at your opponent''s car, as well as evading the missiles your opponent fires at your car. Each time one of the respective cars is struck by a missile, the player controlling the other car receives one point. Victory is achieved through the scoring of twenty-five points. The game itself has four different mazes, and options concerning missile speed, and other factors, within the context of its nine variants, selectable via the Game Select switch. The Difficulty Switches control the rate of fire each car is capable of.' FROM games WHERE igdb_id = 18422 ON CONFLICT (game_id, language_code) DO NOTHING;
