INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('computer-golf', 41548, '1978-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobroc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9nxq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Computer Golf', 'Press 1, 2, 3, or 4 on the alpha-numeric keyboard to correspond with the number of players. The first hole and an electronic golfer will appear on the screen. The number at the top right of the screen indicates the hole being played. The player''s scores will appear at the top left of screen in order of play. The first player''s score will be farthest left. The fourth player''s score will be at the farthest right. If you are playing on a color TV, the color of your score will match the color of your electronic golfer. Once the ball is on the green (the lighter geometric segment of the course) the TV picture will automatically change to a close-up of the green so that the electronic golfer can putt out. The trees on the course are hazards and will stop the flight of the ball. A drive into the trees will elicit a very human reaction from the electronic golfers. The dark area outside the course is the "rough." A ball must be hit back on the course when it''s in the "rough." The golfers cannot drive through the rough to get to the green. Each golfer plays through the entire hole before it is the next golfer''s turn. Use the joy stick of the hand control units to walk the electronic golfers around the course. The left hand control is shared by players 1 and 3. The right hand control is shared by players 2 and 4. The direction of the joy stick controls the direction the electronic golfers will walk. They will walk in all vertical, horizontal and diagonal directions in accordance with the joy stick''s position. The toe of the club must overlap the ball at the start of the backswing. The action button on the hand control unit controls the swing of the club. Press down to start the backswing. The longer you press the action button, the higher the backswing. The distance traveled by the ball is determined by the length of the backswing. If you bring the backswing full circle, the club will release automatically, and the distance the ball travels will be random. Release the action button to hit the ball. The backswing of the club will always be clockwise, and the downswing will always be counter-clockwise. The direction taken by the ball will be dependent on the golfer''s position in relation to it. It will be perpendicular to the angle of the toe of the club when it makes contact with the ball. You can walk your electronic golfer away from the ball and take a practice swing to confirm direction. There is no stroke penalty for this. If you are addressing the ball and starting your backswing, but wish to change the position of your electronic golfer - simply walk him away from the ball and release the action button. There is no penalty The player with the lowest score for the nine holes is the winner. To play again, press the RESET key on the console and then press 1, 2, 3 or 4 on the alpha-numeric keyboard. COMPUTER GOLF! Nine holes. Par 36 Hole 1 - Par 4 Hole 2 - Par 4 Hole 3 - Par 3 Hole 4 - Par 4 Hole 5 - Par 5 Hole 6 - Par 3 Hole 7 - Par 4 Hole 8 - Par 5 Hole 9 - Par 4' FROM games WHERE igdb_id = 41548 ON CONFLICT (game_id, language_code) DO NOTHING;
