INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Billiards!', 'In this pool title, two players can choose either one of the two games available: 8-ball or Rotation. The games are selected by pressing any direction of the joystick while their names are displayed on screen. In the 8-ball game, the winner is the first player to sink either one of the two black balls in game. In Rotation, the black balls are replaced by colored ones, and the winner is the player to sink the most balls. By sinking one ball, the player gets the chance to try another shot. There are no penalties for missing the balls or sinking the white one. Players can choose the direction of the shot (by rotating the cue around the white ball) and the strength of the shot (the longer the action button is pressed, the harder the shot is).' FROM games WHERE igdb_id = 41559 ON CONFLICT (game_id, language_code) DO NOTHING;
