INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Computer Othello', 'An arcade video game released in 1978 exclusively in Japan. It was the first video game both published and developed by Nintendo, and the first game developed by Nintendo R&D1. The game was a computerized version of the board game Othello (also known as Reversi). The game allowed for one person to play Othello against a computer opponent. It was also possible for two people to play head to head.' FROM games WHERE igdb_id = 242573 ON CONFLICT (game_id, language_code) DO NOTHING;
