INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elementary math / Bingo Math', 'Elementary math / Bingo Math is a collection of two educational math games. The game helps improve skills in addition, subtraction, multiplication and division. Points are awarded based on speed and math problems get harder the higher the current score. Difficulty adjusts automatically to player skill.' FROM games WHERE igdb_id = 169266 ON CONFLICT (game_id, language_code) DO NOTHING;
