INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trampoline', 'This is Exidy''s sequel to Circus. It was originally developed under the name Trapeze, but only one board of this version is known to exist and it is not thought to have been released i North America. The game did however find success in Japan and was released by Taito in several variations under the Trampoline name in upright and tabletop arcade cabinets.' FROM games WHERE igdb_id = 172661 ON CONFLICT (game_id, language_code) DO NOTHING;
