INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('armored-encounter-slash-sub-chase', 93234, '1978-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8hdf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8vzg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armored Encounter! / Sub Chase!', 'Two titles are available in this cart: Armored Encounter! is a clone of Atari''s Combat. Two players control tanks and try to shoot each other the most in a time limit of three minutes. Sub Chase! features a Hawk hunter-killer jet against a Shark missile-launching submarine. One player controls the jet, which scrolls left, and the other controls the submarine, which scrolls right.' FROM games WHERE igdb_id = 93234 ON CONFLICT (game_id, language_code) DO NOTHING;
