INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alto Trek', 'Multiplayer game, developed for Xerox Alto, where each player uses their own Alto workstation to control a starship. The objective of the game is to destroy the enemy without being destroyed. A player can choose between of being a Klingon, Romulan, or Terran. The game can be played by one player, but there will be no enemy to destroy.' FROM games WHERE igdb_id = 232414 ON CONFLICT (game_id, language_code) DO NOTHING;
