INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Road Champions', 'Road Champion was produced by Taito in 1978. Taito released 487 different machines in our database under this trade name, starting in 1967. Other machines made by Taito during the time period Road Champion was produced include Super Block, Trampoline, Acrobat, Super Speed Race V, Top Bowler, Cross Fire, Flying Fortress II, Barricade II, Fisco 400, and Cisco 400. A timed car racing game where players try to race ahead of the opposing cars and cross the finish line first to become the winner.' FROM games WHERE igdb_id = 230767 ON CONFLICT (game_id, language_code) DO NOTHING;
