INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Color TV-Game Racing 112', 'Color TV-Game Racing 112 is the third game in the Color TV series. Unlike the first two games that were tennis games, this one is a racing game that uses a steering and gearstick to race. You would have to drive on a road while dodging oncoming cars. The game later made a cameo appearance in the game WarioWare, Inc.: Mega Microgame$ for the Game Boy Advance. Shigeru Miyamoto worked on this game''s casing and included the stick shift.' FROM games WHERE igdb_id = 220550 ON CONFLICT (game_id, language_code) DO NOTHING;
