INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaxy War', 'Galaxy War is a discrete logic arcade game released by Sega in 1978. It is a shooting game which is very similar to Bullet Mark—four types of targets, such as spacecraft and disks, are aimed at by one or two players. There is a bullet indicator and you can fire the trigger while squeezing the trigger.' FROM games WHERE igdb_id = 171857 ON CONFLICT (game_id, language_code) DO NOTHING;
