INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wildwood', 'Wildwood is a light gun/shooting game released by Sega in 1978. Like most early Sega arcade games it uses discrete logic rather than a microprocessor to produce its gameplay.' FROM games WHERE igdb_id = 171855 ON CONFLICT (game_id, language_code) DO NOTHING;
