INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Football 2', 'Football 2 (or II) was released in 1978. It is the Sequel to the popular Football I game. It adds the functionality of running forward and backward, passing, etc (and actually has a 10 yard playing field, not 9 like Football I). This game also has an ''Easter Egg'' of sorts, if you hold down the ''Pass'' button while turning on the game, you effectively get Pro 3 or Pro 4 difficulty settings for the game play (i.e., if you have the switch on Pro 1, holding down the pass will give you Pro 3, etc. Pro 4 is VERY fast and difficult to play.)' FROM games WHERE igdb_id = 225530 ON CONFLICT (game_id, language_code) DO NOTHING;
