INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sprint One', 'Super One, released in 1978, is a simple b&w overhead-view arcade racing game. It is single player version of Sprint 2 and a sequel to the Championship Sprint and Super Sprint games.' FROM games WHERE igdb_id = 39908 ON CONFLICT (game_id, language_code) DO NOTHING;
