INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('avalanche', 46840, '1978-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vuexwufr8w2y0ww9t8cd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmmu2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avalanche', 'Avalanche is a 2-D game of skill. You control a multi-storied platform with a spinner-knob. Your goal is to prevent the falling rocks from ever reaching the ground. There are six rows of rocks to deal with. You start with a 6-storied platform and you lose one platform per row of rocks cleared. You score points for those rocks you prevent from reaching the ground. Of course, the farther the row of rocks, the smaller and faster they become. Your ultimate goal is to get enough points so that you can continue your game should you lose your first one. Get your hard hat out and prepare to catch some rogue rocks.' FROM games WHERE igdb_id = 46840 ON CONFLICT (game_id, language_code) DO NOTHING;
