INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sprint 1', 'Sprint is a series of overhead-view arcade racers released from 1976 to 1978. "Sprint 2" was the first in the series with the "2" reflecting the number of players, rather than indicating it as a sequel. Sprint 4 and Sprint 8, a 4 player and 8 player version respectively, were released in 1977. Both were full color raster versions of the game. The single player cabinet Sprint 1 was released in 1978.' FROM games WHERE igdb_id = 18393 ON CONFLICT (game_id, language_code) DO NOTHING;
