INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videocart-14: Sonar Search', 'Sonar Search features the basic gameplay idea of Battleship, but with a unique twist. Instead of trying to randomly guess what grid an opponent''s battleship is on, after the player takes a shot, the player will hear a sonar ping noise. The shorter the noise, the closer the player is to hitting a target. In the 1 player game, the player has a limited number of chances to sink the enemy fleet of ships, while in the 2 player game, players take turns trying to sink their opponents ships before having their own ships sunk. This preprogrammed cartridge plugs into the console of the Fairchild Video Entertainment System for more TV fun. This battle on the high seas is sure to score a direct hit with exciting one and two-player games.' FROM games WHERE igdb_id = 41215 ON CONFLICT (game_id, language_code) DO NOTHING;
