INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('frogs', 46803, '1978-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/y9c7ppg8dk55cvtip0jr.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frogs', 'Frogs is a single-player action / platform arcade game released by Sega-Gremlin in 1978. It is the first video game with a jumping character (predating Donkey Kong by 3 years), which by some definitions could make it the first platform game. The player controls a frog on lily pads and attempts to catch (with the frog''s tongue and while jumping) various insects (butterflies and dragonflies) worth different amounts of points in a set amount of time. Frogs is one of the first arcade games to include a static background as part of the arcade cabinet.[citation needed] The game’s graphics are "projected" by laying the monitor flat on its back and reflecting the computer-generated graphics of the frogs and flies toward the player via a mirror at a 45-degree angle. (The game’s graphics were actually generated and shown backward, so the mirror reflection would show letters and numbers properly.)' FROM games WHERE igdb_id = 46803 ON CONFLICT (game_id, language_code) DO NOTHING;
