INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Computer Intro!', 'This cartridge turns your Odyssey2 into an interactive electronic teacher of computer theory and technology! You learn how to talk with a computer in an assembler language! You use the Odyssey2 alpha-numeric keyboard to write a computer program - and enter it into a microprocessor capable of making 100,000 electronic decisions every second! Then you actually run the program and see the exciting results on your television screen! Shut off the power and it erases everything automatically so you can start a new program any time you want!' FROM games WHERE igdb_id = 283015 ON CONFLICT (game_id, language_code) DO NOTHING;
