INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('videocart-17-pinball-challenge', 41224, '1978-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co70b3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fe46syjyonzlzd2cmgu9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videocart-17: Pinball Challenge', 'Although the title of the game may lead players to believe it''s a pinball game, this is actually a Breakout variant. The basic gameplay features the player bouncing a ball off of a paddle into a wall of bricks, chipping them off one brick at a time. Each brick destroyed earns the player points with the low green bricks being worth 1 point each, the middle blue bricks being worth 4 points each, and the red bricks on top rewarding 7 points each. Once the ball bounces off the wall of bricks, it''s up to the player to maneuver the paddle under the falling ball in order to hit it back up into the wall of bricks. The player loses a life if he happens to miss hitting the ball with his paddle and it falls into the abyss. The game ends when 7 balls are lost. To keep up with the pinball motif, the wall of bricks are referred to as different colored skill lanes, the walls on the side that the ball can bounce off of are labeled side rails, and the paddle is referred to as a flipper. The game offers 132 game variations of this basic gameplay idea, some of them for two simultaneous players. Game modes include Pinball Wiz, Crossover, Blok-Shot, Cooperation, Pro Challenge, and Double Blok, with each having variations that can include different sized paddles, ball speeds, invisible bricks, and even a variation where the paddle shrinks each time it hits the ball. This preprogrammed cartridge plugs into the console of the Fairchild Video Entertainment System for more TV fun. Pinball wizards get ready for a real tilt. You''ll flip over these 132 game variations for 1 and 2 players.' FROM games WHERE igdb_id = 41224 ON CONFLICT (game_id, language_code) DO NOTHING;
